const LAYERS  = [{"name":"CLS_BANKS","types":{"LWPOLYLINE":16,"INSERT":448},"total":464,"color_idx":251,"color":"#86EFAC","category":"Landscape"},{"name":"CLS_BUILDINGS","types":{"LWPOLYLINE":40,"INSERT":1},"total":41,"color_idx":251,"color":"#60A5FA","category":"Structures"},{"name":"CLS_CABLES","types":{"LWPOLYLINE":5},"total":5,"color_idx":251,"color":"#FACC15","category":"Services"},{"name":"CLS_CONTOURS","types":{"LWPOLYLINE":422,"TEXT":121},"total":543,"color_idx":251,"color":"#F1F5F9","category":"Survey"},{"name":"CLS_DETAIL","types":{"INSERT":61,"TEXT":2},"total":63,"color_idx":251,"color":"#94A3B8","category":"Annotation"},{"name":"CLS_DRAINAGE","types":{"INSERT":79,"LWPOLYLINE":1,"TEXT":29},"total":109,"color_idx":251,"color":"#22D3EE","category":"Services"},{"name":"CLS_FENCE","types":{"INSERT":752,"TEXT":8},"total":760,"color_idx":251,"color":"#6EE7B7","category":"Landscape"},{"name":"CLS_GRID","types":{"TEXT":66,"LINE":33},"total":99,"color_idx":251,"color":"#475569","category":"Survey"},{"name":"CLS_KERBS","types":{"LWPOLYLINE":86},"total":86,"color_idx":251,"color":"#FBBF24","category":"Highway"},{"name":"CLS_KERB_DROP","types":{"LWPOLYLINE":14},"total":14,"color_idx":251,"color":"#D97706","category":"Highway"},{"name":"CLS_KERB_TOP","types":{"LWPOLYLINE":46},"total":46,"color_idx":251,"color":"#F59E0B","category":"Highway"},{"name":"CLS_LEVELS","types":{"TEXT":1793,"INSERT":1793},"total":3586,"color_idx":251,"color":"#38BDF8","category":"Survey"},{"name":"CLS_ROADS","types":{"LWPOLYLINE":87},"total":87,"color_idx":251,"color":"#F97316","category":"Highway"},{"name":"CLS_ROAD_LINES","types":{"INSERT":589},"total":589,"color_idx":251,"color":"#FB923C","category":"Highway"},{"name":"CLS_ROOF","types":{"LWPOLYLINE":41,"INSERT":174,"TEXT":167},"total":382,"color_idx":251,"color":"#A78BFA","category":"Structures"},{"name":"CLS_SERVICES","types":{"INSERT":120,"LWPOLYLINE":1,"TEXT":92},"total":213,"color_idx":251,"color":"#FDE68A","category":"Services"},{"name":"CLS_STATION","types":{"INSERT":61,"TEXT":118},"total":179,"color_idx":251,"color":"#FF6B6B","category":"Survey"},{"name":"CLS_STEPS","types":{"LWPOLYLINE":7},"total":7,"color_idx":251,"color":"#C084FC","category":"Structures"},{"name":"CLS_STREAM","types":{"LWPOLYLINE":5,"INSERT":4,"TEXT":4},"total":13,"color_idx":251,"color":"#0EA5E9","category":"Services"},{"name":"CLS_TEXT","types":{"TEXT":56,"INSERT":49,"MTEXT":8},"total":113,"color_idx":251,"color":"#CBD5E1","category":"Annotation"},{"name":"CLS_VEGETATION","types":{"INSERT":2271,"TEXT":8},"total":2279,"color_idx":251,"color":"#4ADE80","category":"Landscape"},{"name":"CLS_WALLS","types":{"LWPOLYLINE":74,"INSERT":32,"TEXT":18},"total":124,"color_idx":251,"color":"#818CF8","category":"Structures"}];
const ORIGIN  = {"e":287676.925,"n":62656.831};
const Z_RANGE = [122.43,134.93];
const X0=180,X1=300,Y0=300,Y1=360;

// Lookup "x,y" → cell
const CMAP = Object.fromEntries(CELLS.map(c=>[`${c.x},${c.y}`,c]));
const ALL_X = Array.from({length:X1-X0+1},(_,i)=>X0+i);
const ALL_Y = Array.from({length:Y1-Y0+1},(_,i)=>Y0+i);
const CATS  = [...new Set(LAYERS.map(l=>l.category))];

const REAL_COUNT  = CELLS.filter(c=>c.i===0).length;
const INTERP_COUNT= CELLS.filter(c=>c.i===1).length;

function elevColor(z: number){
  const t=Math.max(0,Math.min(1,(z-Z_RANGE[0])/(Z_RANGE[1]-Z_RANGE[0])));
  const s:[number,[number,number,number]][]=[[0,[10,60,120]],[0.2,[20,130,160]],[0.4,[60,170,100]],
           [0.6,[160,200,70]],[0.75,[220,170,50]],[0.9,[210,100,40]],[1,[180,50,30]]];
  let c0:[number,number,number]=s[0][1],c1:[number,number,number]=s[1][1],f=0;
  for(let i=0;i<s.length-1;i++){
    if(t>=s[i][0]&&t<=s[i+1][0]){
      f=(t-s[i][0])/(s[i+1][0]-s[i][0]);c0=s[i][1];c1=s[i+1][1];break;
    }
  }
  return `rgb(${Math.round(c0[0]+f*(c1[0]-c0[0]))},${Math.round(c0[1]+f*(c1[1]-c0[1]))},${Math.round(c0[2]+f*(c1[2]-c0[2]))})`;
}

export default function SurveyViewer(){
  const [tab,setTab]       = useState("tin");
  const [catFilter,setCat] = useState("All");
  const [search,setSrch]   = useState("");
  const [vis,setVis]       = useState(()=>Object.fromEntries(LAYERS.map(l=>[l.name,true])));
  const [sk,setSk]         = useState("name");
  const [sd,setSd]         = useState("asc");
  const [tinHover,setTinHover] = useState(null);

  const canvasRef  = useRef(null);
  const transform  = useRef({x:0,y:0,scale:1});
  const drag       = useRef({active:false,sx:0,sy:0,tx:0,ty:0});

  const gridCanvasRef = useRef(null);
  const gTransform    = useRef({x:0,y:0,scale:1});
  const gDrag         = useRef({active:false,sx:0,sy:0,tx:0,ty:0});

  const draw = useCallback(()=>{
    const canvas = canvasRef.current;
    if(!canvas) return;
    const ctx = canvas.getContext("2d");
    if(!ctx) return;
    const {x:tx,y:ty,scale} = transform.current;
    const W=canvas.width, H=canvas.height;

    ctx.clearRect(0,0,W,H);
    ctx.fillStyle="#0A0E17"; ctx.fillRect(0,0,W,H);

    if(!canvas.dataset.ready){
      const dw=X1-X0, dh=Y1-Y0;
      const s=Math.min(W*0.85/dw, H*0.85/dh);
      transform.current={scale:s, x:W/2-(X0+dw/2)*s, y:H/2+(Y0+dh/2)*s};
      canvas.dataset.ready="1";
      draw(); return;
    }

    const ts=(gx,gy)=>[gx*scale+tx, -gy*scale+ty];

    // Clip all terrain rendering to site boundary
    ctx.save();
    ctx.beginPath();
    for(const ring of BOUNDARY){
      ring.forEach(([bx,by],i)=>{const [sx,sy]=ts(bx,by);i===0?ctx.moveTo(sx,sy):ctx.lineTo(sx,sy);});
      ctx.closePath();
    }
    ctx.clip();

    // Raster base layer
    const gw=X1-X0+1, gh=Y1-Y0+1;
    const off=new OffscreenCanvas(gw,gh);
    const octx=off.getContext("2d")!;
    const imgd=octx.createImageData(gw,gh);
    const d=imgd.data;
    for(const c of CELLS){
      if(c.z<=0) continue;
      const px=c.x-X0, py=Y1-c.y;
      const idx=(py*gw+px)*4;
      const rgb=elevColor(c.z).match(/\d+/g)!;
      d[idx]=+rgb[0]; d[idx+1]=+rgb[1]; d[idx+2]=+rgb[2]; d[idx+3]=255;
    }
    octx.putImageData(imgd,0,0);
    const [imgX,imgY]=ts(X0,Y1+1);
    ctx.drawImage(off,imgX,imgY,gw*scale,gh*scale);

    // triangles
    for(const t of TRIS){
      const [x0,y0,z0,x1,y1,z1,x2,y2,z2,tp]=t;
      const [sx0,sy0]=ts(x0,y0), [sx1,sy1]=ts(x1,y1), [sx2,sy2]=ts(x2,y2);
      ctx.beginPath(); ctx.moveTo(sx0,sy0); ctx.lineTo(sx1,sy1); ctx.lineTo(sx2,sy2); ctx.closePath();
      ctx.fillStyle=elevColor((z0+z1+z2)/3); ctx.fill();
      if(tp===0){ctx.strokeStyle="rgba(0,0,0,0.4)"; ctx.lineWidth=0.7; ctx.stroke();}
    }

    // real points
    const pr=Math.max(2,Math.min(6,scale*0.12));
    for(const c of CELLS){
      if(c.i!==0) continue;
      const [sx,sy]=ts(c.x,c.y);
      ctx.beginPath(); ctx.arc(sx,sy,pr,0,Math.PI*2);
      ctx.fillStyle="#4ADE80"; ctx.fill();
      ctx.strokeStyle="#0A0E17"; ctx.lineWidth=0.5; ctx.stroke();
      if(scale>5){
        ctx.fillStyle="#4ADE80"; ctx.font=`${Math.max(8,scale*0.6)}px monospace`;
        ctx.fillText(c.z.toFixed(2),sx+pr+2,sy-pr);
      }
    }

    ctx.restore();
  },[]);

  const drawGrid = useCallback(()=>{
    const canvas=gridCanvasRef.current; if(!canvas) return;
    const ctx=canvas.getContext("2d"); if(!ctx) return;
    const {x:tx,y:ty,scale}=gTransform.current;
    const W=canvas.width, H=canvas.height;
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle="#0A0E17"; ctx.fillRect(0,0,W,H);
    if(!canvas.dataset.ready){
      const dw=X1-X0, dh=Y1-Y0;
      const s=Math.min(W*0.85/dw,H*0.85/dh);
      gTransform.current={scale:s,x:W/2-(X0+dw/2)*s,y:H/2+(Y0+dh/2)*s};
      canvas.dataset.ready="1"; drawGrid(); return;
    }
    const ts=(gx,gy)=>[gx*scale+tx,-gy*scale+ty];
    ctx.save();
    ctx.beginPath();
    for(const ring of BOUNDARY){
      ring.forEach(([bx,by],i)=>{const [sx,sy]=ts(bx,by);i===0?ctx.moveTo(sx,sy):ctx.lineTo(sx,sy);});
      ctx.closePath();
    }
    ctx.clip();
    for(const c of CELLS){
      const sx=c.x*scale+tx, sy=-(c.y+1)*scale+ty;
      ctx.fillStyle=elevColor(c.z);
      ctx.fillRect(sx,sy,scale,scale);
    }
    if(scale>6){
      ctx.strokeStyle="rgba(0,0,0,0.25)"; ctx.lineWidth=0.4;
      for(const c of CELLS){
        ctx.strokeRect(c.x*scale+tx,-(c.y+1)*scale+ty,scale,scale);
      }
    }
    if(scale>8){
      const fs=Math.max(8,Math.min(scale*0.38,13));
      ctx.font=`${fs}px monospace`;
      ctx.textAlign="center";
      ctx.shadowColor="rgba(0,0,0,0.85)"; ctx.shadowBlur=3;
      for(const c of CELLS){
        ctx.fillStyle=c.i===0?"#86EFAC":"#FFFFFF";
        ctx.fillText(c.z.toFixed(2),c.x*scale+tx+scale/2,-(c.y+1)*scale+ty+scale/2+fs*0.35);
      }
      ctx.shadowBlur=0; ctx.textAlign="start";
    }
    ctx.restore();
  },[]);

  useEffect(()=>{
    const canvas=canvasRef.current; if(!canvas) return;
    canvas.dataset.ready=""; draw();
  },[draw]);

  useEffect(()=>{
    const canvas=canvasRef.current; if(!canvas) return;
    const ro=new ResizeObserver(()=>{
      canvas.width=canvas.offsetWidth; canvas.height=canvas.offsetHeight;
      canvas.dataset.ready=""; draw();
    });
    ro.observe(canvas); return()=>ro.disconnect();
  },[draw]);

  useEffect(()=>{
    const canvas=canvasRef.current; if(!canvas) return;
    const onDown=(e)=>{drag.current={active:true,sx:e.clientX,sy:e.clientY,tx:transform.current.x,ty:transform.current.y};};
    const onMove=(e)=>{
      if(!drag.current.active) return;
      transform.current.x=drag.current.tx+(e.clientX-drag.current.sx);
      transform.current.y=drag.current.ty+(e.clientY-drag.current.sy);
      draw();
    };
    const onUp=()=>{drag.current.active=false;};
    const onWheel=(e)=>{
      e.preventDefault();
      const rect=canvas.getBoundingClientRect();
      const mx=e.clientX-rect.left, my=e.clientY-rect.top;
      const f=e.deltaY<0?1.18:1/1.18;
      transform.current.x=mx+(transform.current.x-mx)*f;
      transform.current.y=my+(transform.current.y-my)*f;
      transform.current.scale*=f;
      draw();
    };
    const onMouseMove=(e)=>{
      const rect=canvas.getBoundingClientRect();
      const sx=e.clientX-rect.left, sy=e.clientY-rect.top;
      const {x:tx,y:ty,scale}=transform.current;
      const gx=(sx-tx)/scale, gy=-(sy-ty)/scale;
      const cx=Math.round(gx), cy=Math.round(gy);
      const c=CMAP[`${cx},${cy}`];
      setTinHover(c?{E:(ORIGIN.e+cx).toFixed(3),N:(ORIGIN.n+cy).toFixed(3),z:c.z,i:c.i}:null);
    };
    canvas.addEventListener("mousedown",onDown);
    canvas.addEventListener("mousemove",onMouseMove);
    canvas.addEventListener("mouseleave",()=>setTinHover(null));
    window.addEventListener("mousemove",onMove);
    window.addEventListener("mouseup",onUp);
    canvas.addEventListener("wheel",onWheel,{passive:false});
    return()=>{
      canvas.removeEventListener("mousedown",onDown);
      canvas.removeEventListener("mousemove",onMouseMove);
      canvas.removeEventListener("mouseleave",()=>setTinHover(null));
      window.removeEventListener("mousemove",onMove);
      window.removeEventListener("mouseup",onUp);
      canvas.removeEventListener("wheel",onWheel);
    };
  },[draw]);

  useEffect(()=>{
    if(tab!=="grid") return;
    const canvas=gridCanvasRef.current; if(!canvas) return;
    canvas.dataset.ready=""; drawGrid();
  },[drawGrid,tab]);

  useEffect(()=>{
    if(tab!=="grid") return;
    const canvas=gridCanvasRef.current; if(!canvas) return;
    const ro=new ResizeObserver(()=>{
      canvas.width=canvas.offsetWidth; canvas.height=canvas.offsetHeight;
      canvas.dataset.ready=""; drawGrid();
    });
    ro.observe(canvas); return()=>ro.disconnect();
  },[drawGrid,tab]);

  useEffect(()=>{
    if(tab!=="grid") return;
    const canvas=gridCanvasRef.current; if(!canvas) return;
    const onDown=(e)=>{gDrag.current={active:true,sx:e.clientX,sy:e.clientY,tx:gTransform.current.x,ty:gTransform.current.y};};
    const onMove=(e)=>{
      if(!gDrag.current.active) return;
      gTransform.current.x=gDrag.current.tx+(e.clientX-gDrag.current.sx);
      gTransform.current.y=gDrag.current.ty+(e.clientY-gDrag.current.sy);
      drawGrid();
    };
    const onUp=()=>{gDrag.current.active=false;};
    const onWheel=(e)=>{
      e.preventDefault();
      const rect=canvas.getBoundingClientRect();
      const mx=e.clientX-rect.left, my=e.clientY-rect.top;
      const f=e.deltaY<0?1.18:1/1.18;
      gTransform.current.x=mx+(gTransform.current.x-mx)*f;
      gTransform.current.y=my+(gTransform.current.y-my)*f;
      gTransform.current.scale*=f;
      drawGrid();
    };
    const onMouseMove=(e)=>{
      const rect=canvas.getBoundingClientRect();
      const sx=e.clientX-rect.left, sy=e.clientY-rect.top;
      const {x:tx,y:ty,scale}=gTransform.current;
      const gx=(sx-tx)/scale, gy=-(sy-ty)/scale;
      const cx=Math.round(gx), cy=Math.round(gy);
      const c=CMAP[`${cx},${cy}`];
      setTinHover(c?{E:(ORIGIN.e+cx).toFixed(3),N:(ORIGIN.n+cy).toFixed(3),z:c.z,i:c.i}:null);
    };
    canvas.addEventListener("mousedown",onDown);
    canvas.addEventListener("mousemove",onMouseMove);
    canvas.addEventListener("mouseleave",()=>setTinHover(null));
    window.addEventListener("mousemove",onMove);
    window.addEventListener("mouseup",onUp);
    canvas.addEventListener("wheel",onWheel,{passive:false});
    return()=>{
      canvas.removeEventListener("mousedown",onDown);
      canvas.removeEventListener("mousemove",onMouseMove);
      canvas.removeEventListener("mouseleave",()=>setTinHover(null));
      window.removeEventListener("mousemove",onMove);
      window.removeEventListener("mouseup",onUp);
      canvas.removeEventListener("wheel",onWheel);
    };
  },[drawGrid,tab]);

  const toggleSort=k=>{if(sk===k)setSd(d=>d==="asc"?"desc":"asc");else{setSk(k);setSd("asc");}};
  const SIco=({k})=><span style={{opacity:sk===k?1:0.3,fontSize:9,marginLeft:3}}>{sk===k?(sd==="asc"?"▲":"▼"):"⇅"}</span>;

  const filtLayers=useMemo(()=>
    LAYERS
      .filter(l=>catFilter==="All"||l.category===catFilter)
      .filter(l=>l.name.toLowerCase().includes(search.toLowerCase()))
      .sort((a,b)=>{const v=typeof a[sk]==="string"?a[sk].localeCompare(b[sk]):(a[sk]??0)-(b[sk]??0);return sd==="asc"?v:-v;})
  ,[catFilter,search,sk,sd]);

  const tbtn=t=>({
    background:"none",border:"none",fontFamily:"inherit",cursor:"pointer",
    borderBottom:tab===t?"2px solid #38BDF8":"2px solid transparent",
    color:tab===t?"#38BDF8":"#475569",
    padding:"11px 18px",fontSize:11,letterSpacing:"0.15em",
  });

  return(
    <div style={{fontFamily:"'Courier New',monospace",background:"#0A0E17",minHeight:"100vh",color:"#CBD5E1"}}>

      <div style={{background:"#0F172A",borderBottom:"1px solid #1E3A5F",
        padding:"13px 22px",display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:10}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <div style={{width:5,height:30,background:"linear-gradient(#38BDF8,#0EA5E9)",borderRadius:2}}/>
          <div>
            <div style={{fontSize:9,color:"#38BDF8",letterSpacing:"0.18em"}}>
              TIN · GRID 1m · DELAUNAY INTERPOLACIÓN · BNG EPSG:27700
            </div>
            <div style={{fontSize:17,fontWeight:"bold",color:"#F1F5F9"}}>XREF_Survey_Topo.dxf</div>
          </div>
        </div>
        <div style={{display:"flex",gap:18,flexWrap:"wrap"}}>
          {[
            ["COLS (ΔE)",X1-X0+1+"m","#38BDF8"],
            ["FILAS (ΔN)",Y1-Y0+1+"m","#FACC15"],
            ["REALES",REAL_COUNT,"#4ADE80"],
            ["INTERPOLADOS",INTERP_COUNT,"#94A3B8"],
            ["Z MIN",Z_RANGE[0]+"m","#22D3EE"],
            ["Z MAX",Z_RANGE[1]+"m","#F97316"],
          ].map(([l,v,c])=>(
            <div key={l}>
              <div style={{fontSize:8,color:"#475569",letterSpacing:"0.1em"}}>{l}</div>
              <div style={{fontSize:13,fontWeight:"bold",color:c}}>{v}</div>
            </div>
          ))}
        </div>
      </div>

      <div style={{background:"#0F172A",borderBottom:"1px solid #1E293B",padding:"0 22px",
        display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex"}}>
          <button style={tbtn("tin")}    onClick={()=>setTab("tin")}>▲ TIN</button>
          <button style={tbtn("grid")}   onClick={()=>setTab("grid")}>▦ RETICULADO</button>
          <button style={tbtn("layers")} onClick={()=>setTab("layers")}>☰ CAPAS</button>
          <button style={tbtn("points")} onClick={()=>setTab("points")}>◎ PUNTOS</button>
        </div>
        {(tab==="tin"||tab==="grid")&&<div style={{display:"flex",gap:12,alignItems:"center"}}>
          <button onClick={()=>{
            if(tab==="tin"&&canvasRef.current){canvasRef.current.dataset.ready="";draw();}
            if(tab==="grid"&&gridCanvasRef.current){gridCanvasRef.current.dataset.ready="";drawGrid();}
          }} style={{fontSize:10,padding:"3px 10px",background:"#1E293B",color:"#94A3B8",border:"1px solid #334155",cursor:"pointer",fontFamily:"inherit"}}>
            ⟳ reset
          </button>
          <span style={{fontSize:10,color:"#475569"}}>scroll=zoom · drag=pan</span>
        </div>}
      </div>

      <div style={{padding:"0 22px 16px"}}>

        {tab==="tin"&&<div style={{position:"relative",height:"calc(100vh - 160px)",minHeight:400}}>
          {tinHover&&(
            <div style={{position:"absolute",top:8,left:8,zIndex:10,background:"rgba(15,23,42,0.9)",
              border:"1px solid #1E3A5F",borderRadius:6,padding:"8px 14px",
              fontFamily:"monospace",fontSize:11,pointerEvents:"none",display:"flex",gap:16}}>
              <div>
                <div style={{fontSize:8,color:"#475569",letterSpacing:"0.1em"}}>EASTING</div>
                <div style={{color:"#FACC15",fontWeight:"bold"}}>E {tinHover.E}</div>
              </div>
              <div>
                <div style={{fontSize:8,color:"#475569",letterSpacing:"0.1em"}}>NORTHING</div>
                <div style={{color:"#FACC15",fontWeight:"bold"}}>N {tinHover.N}</div>
              </div>
              <div>
                <div style={{fontSize:8,color:"#475569",letterSpacing:"0.1em"}}>Z AOD</div>
                <div style={{color:elevColor(tinHover.z),fontWeight:"bold",fontSize:14}}>{tinHover.z.toFixed(3)} m</div>
              </div>
              <div style={{display:"flex",alignItems:"center",gap:6}}>
                <div style={{width:16,height:16,borderRadius:3,background:elevColor(tinHover.z),border:"1px solid #334155"}}/>
                <span style={{fontSize:9,color:tinHover.i===0?"#4ADE80":"#94A3B8"}}>
                  {tinHover.i===0?"● real":"○ interp"}
                </span>
              </div>
            </div>
          )}
          <canvas ref={canvasRef} style={{width:"100%",height:"100%",display:"block",cursor:"crosshair"}}/>
          <div style={{position:"absolute",bottom:8,left:8,display:"flex",alignItems:"center",gap:8,
            background:"rgba(15,23,42,0.85)",padding:"5px 10px",borderRadius:5,pointerEvents:"none"}}>
            <span style={{fontSize:9,color:"#475569"}}>{Z_RANGE[0]}m</span>
            <div style={{width:140,height:7,borderRadius:3,background:
              "linear-gradient(to right,rgb(10,60,120),rgb(20,130,160),rgb(60,170,100),rgb(160,200,70),rgb(220,170,50),rgb(210,100,40),rgb(180,50,30))"}}/>
            <span style={{fontSize:9,color:"#475569"}}>{Z_RANGE[1]}m</span>
            <div style={{width:8,height:8,borderRadius:"50%",background:"#4ADE80",marginLeft:6}}/>
            <span style={{fontSize:9,color:"#4ADE80"}}>{REAL_COUNT} puntos reales</span>
            <span style={{fontSize:9,color:"#475569",marginLeft:4}}>{TRIS.length} triángulos</span>
          </div>
        </div>}

        {tab==="grid"&&<div style={{position:"relative",height:"calc(100vh - 160px)",minHeight:400}}>
          {tinHover&&(
            <div style={{position:"absolute",top:8,left:8,zIndex:10,background:"rgba(15,23,42,0.9)",
              border:"1px solid #1E3A5F",borderRadius:6,padding:"8px 14px",
              fontFamily:"monospace",fontSize:11,pointerEvents:"none",display:"flex",gap:16}}>
              <div><div style={{fontSize:8,color:"#475569",letterSpacing:"0.1em"}}>EASTING</div>
                <div style={{color:"#FACC15",fontWeight:"bold"}}>E {tinHover.E}</div></div>
              <div><div style={{fontSize:8,color:"#475569",letterSpacing:"0.1em"}}>NORTHING</div>
                <div style={{color:"#FACC15",fontWeight:"bold"}}>N {tinHover.N}</div></div>
              <div><div style={{fontSize:8,color:"#475569",letterSpacing:"0.1em"}}>Z AOD</div>
                <div style={{color:elevColor(tinHover.z),fontWeight:"bold",fontSize:14}}>{tinHover.z.toFixed(3)} m</div></div>
              <div style={{display:"flex",alignItems:"center",gap:6}}>
                <div style={{width:16,height:16,borderRadius:3,background:elevColor(tinHover.z),border:"1px solid #334155"}}/>
                <span style={{fontSize:9,color:tinHover.i===0?"#4ADE80":"#94A3B8"}}>{tinHover.i===0?"● real":"○ interp"}</span>
              </div>
            </div>
          )}
          <canvas ref={gridCanvasRef} style={{width:"100%",height:"100%",display:"block",cursor:"crosshair"}}/>
          <div style={{position:"absolute",bottom:8,left:8,display:"flex",alignItems:"center",gap:8,
            background:"rgba(15,23,42,0.85)",padding:"5px 10px",borderRadius:5,pointerEvents:"none"}}>
            <span style={{fontSize:9,color:"#475569"}}>{Z_RANGE[0]}m</span>
            <div style={{width:140,height:7,borderRadius:3,background:
              "linear-gradient(to right,rgb(10,60,120),rgb(20,130,160),rgb(60,170,100),rgb(160,200,70),rgb(220,170,50),rgb(210,100,40),rgb(180,50,30))"}}/>
            <span style={{fontSize:9,color:"#475569"}}>{Z_RANGE[1]}m</span>
            <span style={{fontSize:9,color:"#94A3B8",marginLeft:6}}>{REAL_COUNT} reales · {INTERP_COUNT} interpolados · zoom&gt;6 = rejilla · zoom&gt;14 = etiquetas</span>
          </div>
        </div>}

        {tab==="layers"&&<>
          <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap",alignItems:"center"}}>
            <input placeholder="🔍 buscar..." value={search} onChange={e=>setSrch(e.target.value)}
              style={{background:"#1E293B",border:"1px solid #334155",color:"#CBD5E1",
                padding:"7px 13px",borderRadius:6,fontSize:12,outline:"none",fontFamily:"inherit",width:185}}/>
            <select value={catFilter} onChange={e=>setCat(e.target.value)}
              style={{background:"#1E293B",border:"1px solid #334155",color:"#CBD5E1",
                padding:"7px 13px",borderRadius:6,fontSize:11,outline:"none",fontFamily:"inherit",cursor:"pointer"}}>
              <option>All</option>
              {CATS.map(c=><option key={c}>{c}</option>)}
            </select>
            <span style={{marginLeft:"auto",fontSize:10,color:"#475569"}}>{filtLayers.length}/{LAYERS.length} capas</span>
          </div>
          <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:12}}>
            {CATS.map(cat=>{
              const col=LAYERS.find(l=>l.category===cat)?.color||"#64748B";
              const on=catFilter===cat;
              return(
                <div key={cat} onClick={()=>setCat(on?"All":cat)}
                  style={{background:on?col+"22":"#1E293B",border:`1px solid ${on?col:"#334155"}`,
                    borderRadius:100,padding:"3px 11px",fontSize:10,color:on?col:"#64748B",
                    cursor:"pointer",display:"flex",alignItems:"center",gap:5}}>
                  <div style={{width:6,height:6,borderRadius:"50%",background:col}}/>{cat}
                </div>
              );
            })}
          </div>
          <div style={{overflowX:"auto",borderRadius:8,border:"1px solid #1E3A5F"}}>
            <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
              <thead>
                <tr style={{background:"#0D1525",borderBottom:"1px solid #1E3A5F"}}>
                  {[["",""],["name","CAPA"],["category","CATEGORÍA"],["total","ENTIDADES"],["","TIPOS"],["","VIS"]].map(([k,lbl],i)=>(
                    <th key={i} onClick={()=>k&&toggleSort(k)}
                      style={{padding:"10px 14px",textAlign:"left",color:"#38BDF8",
                        fontSize:9,letterSpacing:"0.12em",fontWeight:"normal",
                        cursor:k?"pointer":"default",userSelect:"none",whiteSpace:"nowrap"}}>
                      {lbl}{k&&<SIco k={k}/>}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtLayers.map((ly,i)=>(
                  <tr key={ly.name} style={{background:i%2===0?"#0D1525":"#0A0E17",
                    borderBottom:"1px solid #131D2E",opacity:vis[ly.name]?1:0.35,transition:"opacity 0.2s"}}>
                    <td style={{padding:"9px 14px"}}>
                      <div style={{width:10,height:10,borderRadius:"50%",background:ly.color,boxShadow:`0 0 5px ${ly.color}80`}}/>
                    </td>
                    <td style={{padding:"9px 14px",color:"#E2E8F0"}}>{ly.name}</td>
                    <td style={{padding:"9px 14px"}}>
                      <span style={{background:ly.color+"20",border:`1px solid ${ly.color}50`,
                        color:ly.color,padding:"2px 10px",borderRadius:100,fontSize:10}}>{ly.category}</span>
                    </td>
                    <td style={{padding:"9px 14px",color:"#FACC15",fontVariantNumeric:"tabular-nums"}}>{ly.total.toLocaleString()}</td>
                    <td style={{padding:"9px 14px",color:"#64748B",fontSize:10}}>
                      {Object.entries(ly.types).map(([t,n])=>`${t}×${n}`).join(" · ")}
                    </td>
                    <td style={{padding:"9px 14px"}}>
                      <div onClick={()=>setVis(p=>({...p,[ly.name]:!p[ly.name]}))}
                        style={{width:28,height:15,borderRadius:100,cursor:"pointer",
                          background:vis[ly.name]?"#0EA5E9":"#1E293B",border:"1px solid #334155",
                          display:"flex",alignItems:"center",padding:"0 3px",
                          justifyContent:vis[ly.name]?"flex-end":"flex-start",transition:"all 0.2s"}}>
                        <div style={{width:10,height:10,borderRadius:"50%",background:"#fff"}}/>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>}

        {tab==="points"&&<>
          <div style={{fontSize:10,color:"#475569",marginBottom:10}}>
            {REAL_COUNT} puntos reales · {INTERP_COUNT} interpolados · sección E287857→287977 N62957→63017
          </div>
          <div style={{overflowY:"auto",maxHeight:520,borderRadius:8,border:"1px solid #1E3A5F"}}>
            <table style={{width:"100%",borderCollapse:"collapse",fontSize:11}}>
              <thead style={{position:"sticky",top:0,zIndex:1}}>
                <tr style={{background:"#0D1525",borderBottom:"1px solid #1E3A5F"}}>
                  {["#","EASTING","NORTHING","Z (m AOD)","TIPO","NIVEL"].map((h,i)=>(
                    <th key={i} style={{padding:"10px 14px",textAlign:"left",color:"#38BDF8",fontSize:9,letterSpacing:"0.1em",fontWeight:"normal"}}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {CELLS.filter(c=>c.i===0).map((c,i)=>(
                  <tr key={i} style={{background:i%2===0?"#0D1525":"#0A0E17",borderBottom:"1px solid #0F1525"}}>
                    <td style={{padding:"6px 14px",color:"#334155",fontVariantNumeric:"tabular-nums"}}>{String(i+1).padStart(4,"0")}</td>
                    <td style={{padding:"6px 14px",color:"#FACC15",fontVariantNumeric:"tabular-nums"}}>{(ORIGIN.e+c.x).toFixed(3)}</td>
                    <td style={{padding:"6px 14px",color:"#FACC15",fontVariantNumeric:"tabular-nums"}}>{(ORIGIN.n+c.y).toFixed(3)}</td>
                    <td style={{padding:"6px 14px",fontWeight:"bold",fontVariantNumeric:"tabular-nums",color:elevColor(c.z)}}>{c.z.toFixed(3)}</td>
                    <td style={{padding:"6px 14px"}}>
                      <span style={{fontSize:9,color:"#4ADE80",border:"1px solid #4ADE8040",
                        background:"#4ADE8015",padding:"1px 8px",borderRadius:100}}>real</span>
                    </td>
                    <td style={{padding:"6px 14px"}}>
                      <div style={{display:"flex",alignItems:"center",gap:5}}>
                        <div style={{width:52,height:5,background:"#1E293B",borderRadius:3,overflow:"hidden"}}>
                          <div style={{width:`${((c.z-Z_RANGE[0])/(Z_RANGE[1]-Z_RANGE[0])*100).toFixed(0)}%`,height:"100%",background:elevColor(c.z),borderRadius:3}}/>
                        </div>
                        <span style={{fontSize:9,color:"#475569"}}>{((c.z-Z_RANGE[0])/(Z_RANGE[1]-Z_RANGE[0])*100).toFixed(0)}%</span>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>}

      </div>
    </div>
  );
}